const input=$json.body??$json;
const s=v=>String(v??'').trim();
const first=(...v)=>v.find(x=>x!==undefined&&x!==null&&x!=='');
const packet=input.packet??input.underwriting_packet??{};
const identity=packet.identity??input.identity??{};
const leadId=s(first(input.lead_id,identity.lead_id));
const propertyId=s(first(input.property_id,identity.property_id));
const dealId=s(first(input.deal_id,identity.deal_id));
const id=s(first(dealId,propertyId,leadId));
const requestId=s(input.request_id??packet.request_id)||('underwriting-audit:'+(id||'unknown')+':v1');
const decision=input.decision??input.mao_decision??input.underwriting_decision??{};
const evidence=packet.evidence??input.evidence??{};
const quality=packet.evidence_quality??input.evidence_quality??input.source_quality??{};
const assumptions=input.assumptions??decision.assumptions??{};
const risks=input.risks??decision.risks??[];
const rationale=first(decision.rationale,decision.reason,decision.explanation,'No decision rationale supplied.');
const recommendedOffer=first(decision.recommended_offer,decision.mao,decision.max_allowable_offer,decision.offer);
const status=s(first(decision.status,input.status,'unknown')).toLowerCase();
const evidenceKeys=['valuation','comps','repairs','risk','buyer_demand','exit_strategy'];
const evidenceSnapshot={};
for(const k of evidenceKeys)evidenceSnapshot[k]={present:evidence[k]!==undefined&&evidence[k]!==null&&evidence[k]!=='',value:evidence[k]};
const auditId='underwriting-decision:'+(id||'unknown')+':'+requestId+':v1';
const audit={audit_id:auditId,request_id:requestId,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},decision:{status,recommended_offer:recommendedOffer??null,rationale,assumptions,risks},evidence_snapshot:evidenceSnapshot,evidence_quality:quality,policy:{economic_viability_primary:true,reference_70pct_secondary_only:true,property_type_specific_logic:true},trace:{source_workflow:s(input.source_workflow)||'wf-114',packet_id:s(packet.packet_id),audited_at:new Date().toISOString()}};
const complete=!!id&&!!recommendedOffer&&rationale!=='No decision rationale supplied.'&&evidenceKeys.every(k=>evidenceSnapshot[k].present);
return[{json:{ok:complete,status:complete?'decision_audit_ready':'decision_audit_incomplete',audit,missing_requirements:[...(!id?['canonical_identity']:[]),...(!recommendedOffer?['recommended_offer']:[]),...(rationale==='No decision rationale supplied.'?['decision_rationale']:[]),...evidenceKeys.filter(k=>!evidenceSnapshot[k].present).map(k=>'evidence:'+k)],next_workflow:complete?'wf-115-underwriting-decision-persistence':'human_review'}}}];
